CREATE UNIQUE INDEX UX_STOCK ON T_STOCK(ID);
INSERT INTO T_STOCK (ID, QTY) SELECT ID, QTY FROM S_IN WHERE true ON CONFLICT(ID) DO UPDATE SET QTY = excluded.QTY WHERE excluded.QTY > T_STOCK.QTY;
