UPDATE EMP
   SET SAL = SAL + (SELECT MAX(SAL) FROM EMP)
 WHERE DEPT = 10;
SELECT SUM(SAL) AS TOTAL FROM EMP;

DELETE FROM EMP
 WHERE SAL < (SELECT AVG(SAL) FROM EMP);
SELECT COUNT(*) AS CNT FROM EMP;
